function clock(){const now=new Date();const time=now.toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});$('#clock').textContent=time;$('#syncTime').textContent=time;$('#date').textContent=now.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',weekday:'long',timeZone:'Asia/Shanghai'}).replaceAll('/','.');}clock();setInterval(clock,1000);
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function openModal(title,body){$('#detail').hidden=true;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modalClose').focus();}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow='';}
