function makeWindowTexture(){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const c=canvas.getContext('2d');c.fillStyle='#32647e';c.fillRect(0,0,256,256);for(let y=0;y<256;y+=32){c.fillStyle='#a3c7d7';c.fillRect(0,y,256,5);for(let x=0;x<256;x+=21){c.fillStyle=((x+y)%5===0)?'#69b4cc':'#2a607c';c.fillRect(x+2,y+8,16,21);c.fillStyle='#6797ad';c.fillRect(x+2,y+8,16,2);c.fillStyle='#c5deeb55';c.fillRect(x+2,y+8,2,21);}}const t=new THREE.CanvasTexture(canvas);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t;}
